input.content:
:root {
  --bg: #06080f;
  --bg-2: #0a1020;
  --panel: rgba(15, 22, 40, 0.86);
  --panel-2: rgba(22, 31, 54, 0.72);
  --line: rgba(129, 163, 226, 0.17);
  --line-strong: rgba(129, 163, 226, 0.34);
  --text: #e9eefc;
  --muted: #8b99b9;
  --gold: #e8c26a;
  --gold-2: #f7df9e;
  --cyan: #5eead4;
  --cyan-2: #9ffcf0;
  --red: #ff6473;
  --violet: #b18cff;
  --green: #77e09a;
  --monster: #e8b45e;
  --spell: #4fd1b4;
  --trap: #b18cff;
  --shadow: 0 18px 60px rgba(0, 0, 0, 0.45);
  --radius: 14px;
  --font: "Hiragino Kaku Gothic ProN", "Hiragino Sans", "Yu Gothic", "YuGothic",
    "Noto Sans JP", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --mono: "SFMono-Regular", "Cascadia Code", "Roboto Mono", Menlo, Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html {
  color-scheme: dark;
}

body {
  margin: 0;
  min-height: 100dvh;
  background:
    radial-gradient(1200px 700px at 50% -10%, #111b35 0%, transparent 60%),
    linear-gradient(180deg, #070a13 0%, #05070d 100%);
  color: var(--text);
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

.bg-grid {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(100, 140, 220, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(100, 140, 220, 0.055) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(circle at 50% 35%, black, transparent 78%);
  z-index: 0;
}

.bg-glow {
  position: fixed;
  width: 50vw;
  height: 50vw;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.16;
  pointer-events: none;
  z-index: 0;
}

.bg-glow-a {
  top: -18vw;
  left: -12vw;
  background: #2f6bff;
}

.bg-glow-b {
  right: -15vw;
  bottom: -20vw;
  background: #00c9a7;
}

#app {
  position: relative;
  z-index: 1;
  width: min(1220px, 100%);
  margin: 0 auto;
  padding: 18px clamp(12px, 2.6vw, 30px) 40px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 4px 2px 18px;
}

.brand {
  display: flex;
  align-items: baseline;
  gap: 14px;
  min-width: 0;
}

.logo {
  font-family: "Arial Black", "Helvetica Neue", Impact, var(--font);
  font-size: clamp(26px, 3.6vw, 40px);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.04em;
  background: linear-gradient(100deg, #fff7db 0%, var(--gold) 46%, #b9852e 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 18px rgba(232, 194, 106, 0.22));
  white-space: nowrap;
}

.logo-arrow {
  display: inline-block;
  padding: 0 0.04em;
  -webkit-text-fill-color: transparent;
  background: linear-gradient(100deg, var(--cyan), #8ab4ff);
  -webkit-background-clip: text;
  background-clip: text;
}

.brand-sub {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  white-space: nowrap;
}

.brand-sub .sep {
  color: rgba(139, 153, 185, 0.45);
}

.brand-sub .jp {
  font-family: var(--font);
  letter-spacing: 0.06em;
}

.top-actions {
  display: flex;
  gap: 8px;
}

.icon-btn {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(16, 24, 43, 0.74);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 15px;
  transition: 0.16s ease;
}

.icon-btn:hover {
  color: var(--gold-2);
  border-color: rgba(232, 194, 106, 0.5);
  transform: translateY(-1px);
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 314px;
  gap: clamp(16px, 2.2vw, 26px);
  align-items: start;
}

.arena {
  min-width: 0;
}

.scoreboard {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 12px;
  align-items: stretch;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(180deg, rgba(24, 34, 60, 0.78), rgba(9, 14, 27, 0.82)),
    radial-gradient(400px 100px at 50% 0%, rgba(94, 234, 212, 0.08), transparent);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.lp-block {
  min-width: 0;
  transition: transform 0.15s ease;
}

.lp-block.player {
  text-align: left;
}

.lp-block.rival {
  text-align: right;
}

.lp-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.lp-block.rival .lp-top {
  flex-direction: row-reverse;
}

.lp-name {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.lp-value {
  font-family: var(--mono);
  font-size: clamp(19px, 2.2vw, 26px);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1;
  color: var(--cyan-2);
}

.lp-block.rival .lp-value {
  color: #ffb3ba;
}

.lp-bar {
  height: 7px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.6);
}

.lp-fill {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2dd4bf, #7af7e5);
  box-shadow: 0 0 14px rgba(94, 234, 212, 0.5);
  transition: width 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.3s;
}

.lp-block.rival .lp-fill {
  margin-left: auto;
  background: linear-gradient(90deg, #ff4d5f, #ff8a96);
  box-shadow: 0 0 14px rgba(255, 100, 115, 0.45);
}

.turn-box {
  align-self: center;
  text-align: center;
  padding: 4px 12px;
  border-left: 1px solid var(--line);
  border-right: 1px solid var(--line);
  min-width: 92px;
}

.turn-main {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  color: var(--gold-2);
}

.turn-sub {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  color: var(--muted);
  margin-top: 2px;
}

.field-head,
.field-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: 12px 2px 7px;
}

.field-foot {
  margin: 9px 2px 10px;
}

.field-tag {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.2em;
}

.rival-tag {
  color: #ff9ba4;
}

.player-tag {
  color: var(--cyan);
}

.zone-count {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--muted);
}

.board-frame {
  position: relative;
  padding: clamp(7px, 1vw, 11px);
  border: 1px solid rgba(116, 151, 218, 0.2);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(30, 42, 70, 0.48), rgba(7, 11, 21, 0.62)),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.015) 0 1px, transparent 1px 12px);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.board-frame::before {
  content: "";
  position: absolute;
  left: 7%;
  right: 7%;
  top: 50%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(232, 194, 106, 0.42), transparent);
  pointer-events: none;
  z-index: 0;
}

.board {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: clamp(4px, 0.8vw, 7px);
  width: 100%;
  max-width: 650px;
  margin: 0 auto;
}

.zone {
  position: relative;
  aspect-ratio: 1 / 1;
  border: 1px solid rgba(113, 147, 210, 0.18);
  border-radius: 9px;
  background:
    radial-gradient(140% 110% at 50% 0%, rgba(78, 105, 165, 0.12), transparent 65%),
    rgba(10, 16, 30, 0.55);
  padding: 0;
  overflow: hidden;
  transition: border-color 0.14s ease, background 0.14s ease, transform 0.14s ease,
    box-shadow 0.14s ease;
  min-width: 0;
}

.zone[data-side="opp"] {
  background:
    radial-gradient(140% 110% at 50% 0%, rgba(164, 54, 74, 0.12), transparent 65%),
    rgba(16, 12, 24, 0.62);
  border-color: rgba(201, 90, 108, 0.18);
}

.zone[data-side="player"] {
  background:
    radial-gradient(140% 110% at 50% 100%, rgba(48, 143, 142, 0.12), transparent 65%),
    rgba(9, 18, 30, 0.62);
  border-color: rgba(79, 189, 174, 0.18);
}

.zone::after {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(255, 255, 255, 0.035);
  border-radius: 6px;
  pointer-events: none;
}

.zone-code {
  position: absolute;
  top: 5px;
  left: 6px;
  font-family: var(--mono);
  font-size: clamp(6px, 0.78vw, 8px);
  letter-spacing: 0.08em;
  color: rgba(168, 187, 222, 0.34);
  pointer-events: none;
}

.zone.is-valid {
  border-color: var(--cyan);
  box-shadow: 0 0 0 1px rgba(94, 234, 212, 0.32), 0 0 24px rgba(94, 234, 212, 0.18);
  background:
    radial-gradient(140% 110% at 50% 50%, rgba(38, 160, 150, 0.26), transparent 72%),
    rgba(9, 25, 35, 0.7);
  cursor: pointer;
  animation: validPulse 1.4s ease-in-out infinite;
}

.zone.is-target {
  border-color: var(--red);
  box-shadow: 0 0 0 1px rgba(255, 100, 115, 0.36), 0 0 24px rgba(255, 100, 115, 0.2);
  cursor: crosshair;
}

.zone.is-hint {
  border-color: var(--gold);
  box-shadow: 0 0 0 1px rgba(232, 194, 106, 0.4), 0 0 26px rgba(232, 194, 106, 0.22);
  animation: hintPulse 1.2s ease-in-out infinite;
}

.zone.is-selected {
  border-color: var(--gold-2);
  box-shadow: 0 0 0 1px rgba(232, 194, 106, 0.5), 0 0 22px rgba(232, 194, 106, 0.18);
}

.zone.is-occupied:hover {
  border-color: rgba(232, 194, 106, 0.55);
}

/* Cards sitting in a zone */
.z-card {
  position: absolute;
  inset: 3px;
  border-radius: 7px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 1px;
  padding: clamp(3px, 0.55vw, 6px);
  text-align: center;
  overflow: hidden;
}

.z-card.type-monster {
  background: linear-gradient(165deg, rgba(84, 56, 24, 0.92), rgba(27, 21, 17, 0.96));
  border: 1px solid rgba(232, 180, 94, 0.52);
  box-shadow: inset 0 0 18px rgba(232, 180, 94, 0.08);
}

.z-card.type-spell {
  background: linear-gradient(165deg, rgba(17, 76, 68, 0.9), rgba(10, 27, 29, 0.96));
  border: 1px solid rgba(79, 209, 180, 0.5);
}

.z-card.type-trap {
  background: linear-gradient(165deg, rgba(67, 38, 105, 0.9), rgba(24, 15, 36, 0.96));
  border: 1px solid rgba(177, 140, 255, 0.5);
}

.z-card.is-defense {
  background: linear-gradient(165deg, rgba(26, 54, 84, 0.92), rgba(12, 23, 38, 0.97));
  border-color: rgba(120, 177, 255, 0.48);
}

.z-card.is-set {
  padding: 0;
  border: 1px solid rgba(126, 146, 201, 0.42);
  background:
    repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.035) 0 5px, transparent 5px 10px),
    radial-gradient(circle at 50% 50%, #1d2a52 0%, #0b1022 68%, #070a14 100%);
}

.z-card.is-set::before {
  content: "";
  position: absolute;
  inset: 7%;
  border: 1px solid rgba(150, 175, 235, 0.24);
  border-radius: 4px;
}

.z-card.is-set::after {
  content: "◆";
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: clamp(14px, 3vw, 26px);
  color: rgba(150, 178, 240, 0.6);
  text-shadow: 0 0 14px rgba(94, 234, 212, 0.24);
}

.z-card .z-icon {
  font-size: clamp(15px, 3vw, 25px);
  line-height: 1.1;
  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.5));
  margin-top: 1px;
}

.z-card .z-name {
  font-size: clamp(6px, 0.96vw, 10px);
  line-height: 1.12;
  font-weight: 700;
  color: #fff3d6;
  word-break: break-word;
  max-width: 100%;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.z-card.type-spell .z-name,
.z-card.type-trap .z-name {
  color: #eafff8;
}

.z-card .z-stats {
  margin-top: auto;
  font-family: var(--mono);
  font-size: clamp(6px, 0.9vw, 9px);
  letter-spacing: -0.02em;
  color: rgba(255, 244, 218, 0.86);
  white-space: nowrap;
  background: rgba(0, 0, 0, 0.28);
  border-radius: 4px;
  padding: 1px 3px;
}

.z-card.is-defense .z-stats {
  color: #cfe6ff;
}

.z-card .z-badge {
  position: absolute;
  top: 3px;
  right: 3px;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.06em;
  padding: 1px 3px;
  border-radius: 3px;
  background: rgba(255, 100, 115, 0.85);
  color: #fff;
}

.z-card .z-badge.def {
  background: rgba(75, 140, 220, 0.9);
}

.z-card .z-badge.equip {
  background: rgba(79, 209, 180, 0.9);
  color: #03201b;
}

.z-card .z-code {
  position: absolute;
  bottom: 3px;
  left: 4px;
  font-family: var(--mono);
  font-size: 6px;
  color: rgba(255, 255, 255, 0.35);
}

.z-card .z-known {
  position: absolute;
  top: 3px;
  left: 3px;
  font-family: var(--mono);
  font-size: 6px;
  padding: 1px 3px;
  border-radius: 3px;
  background: rgba(232, 194, 106, 0.9);
  color: #1a1305;
  font-weight: 700;
}

.zone.is-occupied .zone-code {
  display: none;
}

.damage-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: visible;
  z-index: 30;
}

.damage-float {
  position: absolute;
  left: 75%;
  top: 15%;
  font-family: "Arial Black", Impact, var(--mono);
  font-size: clamp(28px, 4.6vw, 46px);
  font-weight: 900;
  color: #ff5d6c;
  text-shadow: 0 0 18px rgba(255, 70, 90, 0.75), 0 3px 0 rgba(0, 0, 0, 0.45);
  animation: damageFloat 0.95s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
  white-space: nowrap;
}

.lp-block.shake {
  animation: shake 0.42s ease;
}

.status-strip {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.stat {
  display: flex;
  align-items: baseline;
  gap: 5px;
}

.stat-key {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.stat-val {
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
}

.mini-btn {
  padding: 4px 9px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(15, 23, 41, 0.7);
  color: var(--muted);
  font-size: 10px;
  transition: 0.15s ease;
}

.mini-btn:hover {
  color: var(--red);
  border-color: rgba(255, 100, 115, 0.45);
}

.hand-area {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(180deg, rgba(14, 21, 38, 0.82), rgba(8, 12, 23, 0.9));
  padding: 10px 12px 12px;
}

.hand-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.hand-title {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.hand-count {
  display: inline-grid;
  place-items: center;
  min-width: 19px;
  height: 18px;
  margin-left: 5px;
  padding: 0 5px;
  border-radius: 5px;
  background: rgba(232, 194, 106, 0.14);
  color: var(--gold-2);
  font-size: 9px;
}

.hint-btn {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  color: var(--gold);
  border: 1px solid rgba(232, 194, 106, 0.32);
  border-radius: 7px;
  padding: 4px 9px;
  transition: 0.15s ease;
}

.hint-btn:hover {
  background: rgba(232, 194, 106, 0.1);
}

.hint-btn span {
  color: var(--muted);
}

.hand {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 3px 2px 8px;
  scrollbar-width: thin;
  scrollbar-color: rgba(129, 163, 226, 0.3) transparent;
}

.hand::-webkit-scrollbar {
  height: 5px;
}

.hand::-webkit-scrollbar-thumb {
  background: rgba(129, 163, 226, 0.3);
  border-radius: 99px;
}

.hand-card {
  position: relative;
  flex: 0 0 auto;
  width: clamp(88px, 10.6vw, 108px);
  height: clamp(122px, 14.4vw, 146px);
  border: 1px solid var(--line-strong);
  border-radius: 9px;
  background: linear-gradient(165deg, #1b2438, #0c111e);
  padding: 7px 7px 6px;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 3px;
  transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  overflow: hidden;
}

.hand-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  background: var(--monster);
  opacity: 0.9;
}

.hand-card.type-spell::before {
  background: var(--spell);
}

.hand-card.type-trap::before {
  background: var(--trap);
}

.hand-card:hover {
  transform: translateY(-4px);
  border-color: rgba(232, 194, 106, 0.5);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.42);
}

.hand-card.is-selected {
  transform: translateY(-7px);
  border-color: var(--gold-2);
  box-shadow: 0 0 0 1px rgba(232, 194, 106, 0.28), 0 14px 30px rgba(0, 0, 0, 0.5),
    0 0 24px rgba(232, 194, 106, 0.13);
}

.hand-card.is-hint {
  border-color: var(--gold);
  animation: hintPulse 1.2s ease-in-out infinite;
}

.hc-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  margin-top: 2px;
}

.hc-icon {
  font-size: clamp(18px, 2.2vw, 24px);
  line-height: 1;
}

.hc-lv {
  font-family: var(--mono);
  font-size: 7px;
  color: var(--gold-2);
  letter-spacing: 0.02em;
}

.hc-name {
  font-size: clamp(8px, 0.94vw, 10px);
  font-weight: 700;
  line-height: 1.2;
  color: #f6f1e3;
}

.hc-stats {
  margin-top: auto;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted);
}

.hc-type {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.12em;
  color: rgba(139, 153, 185, 0.7);
}

.detail {
  min-height: 38px;
  margin-top: 2px;
  padding: 7px 9px;
  border-left: 2px solid rgba(232, 194, 106, 0.42);
  background: rgba(232, 194, 106, 0.045);
  border-radius: 0 6px 6px 0;
  color: #c9d2e8;
  font-size: 10.5px;
  line-height: 1.55;
}

.detail strong {
  color: var(--gold-2);
}

.detail .d-name {
  color: var(--gold-2);
  font-weight: 700;
}

.detail .d-type {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-left: 6px;
}

.detail .d-stats {
  font-family: var(--mono);
  color: var(--cyan);
  margin-left: 6px;
  font-size: 9px;
}

.action-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-height: 54px;
  margin-top: 10px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(180deg, rgba(19, 28, 49, 0.92), rgba(9, 14, 26, 0.94)),
    radial-gradient(300px 60px at 20% 0%, rgba(94, 234, 212, 0.08), transparent);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.28);
}

.action-hint {
  flex: 1 1 160px;
  min-width: 0;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.45;
}

.action-hint strong {
  color: var(--gold-2);
}

.action-btn {
  padding: 8px 15px;
  border-radius: 8px;
  border: 1px solid var(--line-strong);
  background: rgba(29, 41, 68, 0.85);
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.02em;
  transition: 0.14s ease;
  white-space: nowrap;
}

.action-btn:hover {
  transform: translateY(-1px);
  border-color: rgba(232, 194, 106, 0.55);
  background: rgba(45, 57, 86, 0.95);
}

.action-btn.primary {
  border-color: rgba(232, 194, 106, 0.62);
  background: linear-gradient(180deg, rgba(232, 194, 106, 0.2), rgba(150, 110, 40, 0.18));
  color: var(--gold-2);
}

.action-btn.primary:hover {
  box-shadow: 0 0 20px rgba(232, 194, 106, 0.16);
}

.action-btn.danger {
  border-color: rgba(255, 100, 115, 0.5);
  color: #ffc4ca;
}

.action-btn.ghost {
  background: transparent;
  color: var(--muted);
}

.action-btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
  transform: none;
  border-color: var(--line);
  background: rgba(20, 27, 45, 0.5);
  color: var(--muted);
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: sticky;
  top: 16px;
}

.panel {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(180deg, rgba(16, 24, 43, 0.86), rgba(8, 13, 24, 0.9));
  padding: 13px 14px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.panel h2 {
  margin: 0 0 9px;
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.panel h2 .jp {
  font-family: var(--font);
  letter-spacing: 0.04em;
  font-weight: 400;
  opacity: 0.7;
  margin-left: 4px;
}

.panel-kicker {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.22em;
  color: var(--gold);
}

.puzzle-name {
  margin: 4px 0 0;
  font-size: 24px;
  line-height: 1.2;
  letter-spacing: 0.02em;
}

.puzzle-sub {
  margin: 1px 0 8px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.puzzle-copy {
  margin: 0 0 12px;
  font-size: 10.5px;
  line-height: 1.7;
  color: #aeb9d2;
}

.objective-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.objective {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  color: #c6cfe4;
}

.objective .check {
  flex: 0 0 auto;
  width: 14px;
  height: 14px;
  border: 1px solid rgba(129, 163, 226, 0.4);
  border-radius: 4px;
  display: grid;
  place-items: center;
  font-size: 9px;
  color: transparent;
  background: rgba(0, 0, 0, 0.2);
}

.objective.done .check {
  border-color: var(--cyan);
  background: rgba(94, 234, 212, 0.16);
  color: var(--cyan-2);
}

.objective.done .check::after {
  content: "✓";
}

.objective.done {
  color: var(--cyan-2);
}

.hint-box {
  margin-top: 11px;
  padding: 8px 9px;
  border: 1px solid rgba(232, 194, 106, 0.32);
  border-radius: 7px;
  background: rgba(232, 194, 106, 0.07);
  color: #f5e; /* overwritten below */
  color: #f3e4ba;
  font-size: 10px;
  line-height: 1.55;
}

.hint-box strong {
  color: var(--gold-2);
}

.known-panel .known-card {
  display: flex;
  gap: 9px;
  padding: 8px 0;
  border-top: 1px solid rgba(129, 163, 226, 0.1);
}

.known-panel .known-card:first-of-type {
  border-top: 0;
  padding-top: 1px;
}

.known-icon {
  flex: 0 0 auto;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  font-size: 20px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
}

.known-icon.wall {
  border-color: rgba(120, 177, 255, 0.35);
}

.known-icon.trap {
  border-color: rgba(177, 140, 255, 0.35);
}

.known-name {
  font-size: 10.5px;
  font-weight: 700;
  color: #e5eaf7;
}

.known-card p {
  margin: 2px 0 0;
  font-size: 9.5px;
  line-height: 1.55;
  color: var(--muted);
}

.badge {
  display: inline-block;
  margin-left: 4px;
  padding: 1px 4px;
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.06em;
  vertical-align: 1px;
}

.badge.def {
  background: rgba(120, 177, 255, 0.16);
  color: #a9d1ff;
  border: 1px solid rgba(120, 177, 255, 0.3);
}

.badge.set {
  background: rgba(177, 140, 255, 0.16);
  color: #d8c6ff;
  border: 1px solid rgba(177, 140, 255, 0.3);
}

.log-panel {
  min-height: 110px;
}

.log {
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-height: 150px;
  overflow-y: auto;
  font-family: var(--mono);
  font-size: 8.5px;
  line-height: 1.45;
  color: #aab6d0;
  scrollbar-width: thin;
  scrollbar-color: rgba(129, 163, 226, 0.3) transparent;
}

.log-entry {
  padding-left: 7px;
  border-left: 1px solid rgba(129, 163, 226, 0.22);
}

.log-entry.player {
  border-left-color: rgba(94, 234, 212, 0.5);
  color: #bfe9e2;
}

.log-entry.damage {
  border-left-color: rgba(255, 100, 115, 0.55);
  color: #ffc0c6;
}

.log-entry.danger {
  border-left-color: var(--red);
  color: #ff9aa4;
}

.log-entry.opp {
  border-left-color: rgba(177, 140, 255, 0.55);
  color: #d6c6ff;
}

.record {
  font-family: var(--mono);
  font-size: 15px;
  font-weight: 700;
  color: var(--gold-2);
}

.record span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 400;
}

.record-note {
  margin: 3px 0 0;
  font-size: 8.5px;
  line-height: 1.5;
  color: var(--muted);
}

/* Toast */
.toast {
  position: fixed;
  left: 50%;
  bottom: calc(18px + env(safe-area-inset-bottom));
  transform: translate(-50%, 16px);
  z-index: 80;
  max-width: min(92vw, 440px);
  padding: 9px 15px;
  border: 1px solid rgba(232, 194, 106, 0.45);
  border-radius: 9px;
  background: rgba(12, 18, 32, 0.96);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.55);
  color: #f5e7c0;
  font-size: 11px;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: 0.2s ease;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* Modals */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(3, 5, 10, 0.78);
  backdrop-filter: blur(7px);
  animation: fadeIn 0.18s ease;
}

.modal {
  width: min(560px, 100%);
  max-height: min(88dvh, 720px);
  overflow-y: auto;
  border: 1px solid rgba(232, 194, 106, 0.28);
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(24, 34, 58, 0.98), rgba(9, 14, 26, 0.99)),
    radial-gradient(500px 200px at 50% 0%, rgba(232, 194, 106, 0.08), transparent);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  padding: clamp(18px, 3vw, 28px);
  animation: modalIn 0.22s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.modal.wide {
  width: min(680px, 100%);
}

.modal-kicker {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.24em;
  color: var(--gold);
}

.modal-title {
  margin: 5px 0 4px;
  font-size: clamp(25px, 4.6vw, 38px);
  line-height: 1.15;
  letter-spacing: 0.01em;
}

.modal-title .big {
  font-family: "Arial Black", Impact, var(--mono);
  font-size: 1.35em;
  letter-spacing: -0.04em;
  background: linear-gradient(100deg, #fff6d9, var(--gold) 55%, #d19535);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.modal-sub {
  margin: 0 0 16px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.18em;
  color: var(--muted);
  text-transform: uppercase;
}

.modal p {
  color: #b9c4da;
  font-size: 12px;
  line-height: 1.75;
}

.modal .rule-list {
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.modal .rule-list li {
  position: relative;
  padding-left: 17px;
  font-size: 11px;
  line-height: 1.6;
  color: #bdc7dc;
}

.modal .rule-list li::before {
  content: "▸";
  position: absolute;
  left: 0;
  color: var(--gold);
}

.modal .rule-list strong {
  color: var(--gold-2);
}

.rule-callout {
  margin: 14px 0 0;
  padding: 10px 12px;
  border: 1px solid rgba(94, 234, 212, 0.22);
  border-radius: 8px;
  background: rgba(94, 234, 212, 0.055);
  font-size: 10.5px;
  line-height: 1.65;
  color: #c6f5ee;
}

.modal-actions {
  display: flex;
  gap: 9px;
  flex-wrap: wrap;
  margin-top: 20px;
}

.btn {
  padding: 10px 18px;
  border-radius: 9px;
  border: 1px solid var(--line-strong);
  background: rgba(30, 42, 69, 0.85);
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
  transition: 0.15s ease;
}

.btn:hover {
  transform: translateY(-1px);
  border-color: rgba(232, 194, 106, 0.55);
}

.btn.primary {
  border-color: rgba(232, 194, 106, 0.65);
  background: linear-gradient(180deg, rgba(232, 194, 106, 0.24), rgba(146, 104, 35, 0.22));
  color: #fff1c9;
  box-shadow: 0 0 24px rgba(232, 194, 106, 0.1);
}

.btn.ghost {
  background: transparent;
  color: var(--muted);
}

.btn.wide {
  width: 100%;
  justify-content: center;
}

.picker-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 8px;
  margin-top: 14px;
}

.picker-card {
  text-align: left;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(19, 28, 48, 0.8);
  transition: 0.15s ease;
}

.picker-card:hover {
  border-color: var(--gold);
  transform: translateY(-2px);
  background: rgba(31, 43, 70, 0.9);
}

.picker-card .pc-top {
  display: flex;
  align-items: center;
  gap: 7px;
}

.picker-card .pc-icon {
  font-size: 20px;
}

.picker-card .pc-name {
  font-size: 10.5px;
  font-weight: 700;
  color: #f3eedf;
}

.picker-card .pc-stats {
  margin-top: 5px;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--cyan);
}

.picker-card .pc-text {
  margin-top: 4px;
  font-size: 8.5px;
  line-height: 1.5;
  color: var(--muted);
}

.result-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 16px;
}

.result-stat {
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.025);
  text-align: center;
}

.result-stat .rs-key {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  color: var(--muted);
}

.result-stat .rs-val {
  margin-top: 2px;
  font-family: var(--mono);
  font-size: 19px;
  font-weight: 700;
  color: var(--text);
}

.result-stat .rs-val.gold {
  color: var(--gold-2);
}

.stars {
  font-size: 25px;
  letter-spacing: 5px;
  color: var(--gold);
  text-align: center;
  margin-top: 14px;
  text-shadow: 0 0 20px rgba(232, 194, 106, 0.3);
}

.stars .off {
  color: rgba(139, 153, 185, 0.22);
  text-shadow: none;
}

.new-best {
  display: inline-block;
  margin-left: 6px;
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--gold);
  color: #1b1303;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  vertical-align: 3px;
}

.solution-list {
  counter-reset: step;
  margin: 14px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.solution-list li {
  counter-increment: step;
  position: relative;
  padding: 7px 9px 7px 33px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.02);
  font-size: 10px;
  line-height: 1.5;
  color: #c5cfe3;
}

.solution-list li::before {
  content: counter(step, decimal-leading-zero);
  position: absolute;
  left: 8px;
  top: 7px;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--gold);
}

.solution-list li strong {
  color: var(--gold-2);
}

@keyframes validPulse {
  0%, 100% { box-shadow: 0 0 0 1px rgba(94, 234, 212, 0.32), 0 0 18px rgba(94, 234, 212, 0.14); }
  50% { box-shadow: 0 0 0 1px rgba(94, 234, 212, 0.6), 0 0 30px rgba(94, 234, 212, 0.28); }
}

@keyframes hintPulse {
  0%, 100% { box-shadow: 0 0 0 1px rgba(232, 194, 106, 0.32), 0 0 12px rgba(232, 194, 106, 0.14); }
  50% { box-shadow: 0 0 0 1px rgba(232, 194, 106, 0.7), 0 0 24px rgba(232, 194, 106, 0.3); }
}

@keyframes damageFloat {
  0% { opacity: 0; transform: translate(-50%, 12px) scale(0.7); }
  18% { opacity: 1; transform: translate(-50%, 0) scale(1.08); }
  100% { opacity: 0; transform: translate(-50%, -48px) scale(0.94); }
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-5px); }
  40% { transform: translateX(5px); }
  60% { transform: translateX(-3px); }
  80% { transform: translateX(3px); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes modalIn {
  from { opacity: 0; transform: translateY(14px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (max-width: 980px) {
  .layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .sidebar {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .sidebar .puzzle-panel,
  .sidebar .log-panel {
    grid-column: 1 / -1;
  }

  .log {
    max-height: 120px;
  }
}

@media (max-width: 640px) {
  #app {
    padding: 10px 10px calc(14px + env(safe-area-inset-bottom));
  }

  .topbar {
    padding: 2px 2px 10px;
  }

  .brand {
    gap: 8px;
    flex-direction: column;
    align-items: flex-start;
    gap: 1px;
  }

  .logo {
    font-size: 30px;
  }

  .brand-sub {
    font-size: 8px;
    letter-spacing: 0.12em;
  }

  .brand-sub .jp {
    display: none;
  }

  .icon-btn {
    width: 34px;
    height: 34px;
  }

  .scoreboard {
    padding: 9px 10px;
    gap: 6px;
    border-radius: 12px;
  }

  .turn-box {
    min-width: 66px;
    padding: 2px 4px;
  }

  .turn-main {
    font-size: 9px;
  }

  .turn-sub {
    font-size: 6.5px;
  }

  .lp-name {
    font-size: 8px;
    letter-spacing: 0.14em;
  }

  .lp-value {
    font-size: 18px;
  }

  .lp-bar {
    height: 6px;
  }

  .field-head {
    margin: 9px 2px 5px;
  }

  .field-tag,
  .zone-count {
    font-size: 7.5px;
    letter-spacing: 0.12em;
  }

  .board-frame {
    padding: 5px;
    border-radius: 13px;
  }

  .board {
    gap: 4px;
  }

  .zone {
    border-radius: 6px;
  }

  .z-card {
    inset: 2px;
    border-radius: 5px;
    padding: 2px;
  }

  .z-card .z-icon {
    font-size: 16px;
  }

  .z-card .z-name {
    font-size: 6px;
    -webkit-line-clamp: 1;
  }

  .z-card .z-stats {
    font-size: 6px;
    padding: 0 2px;
  }

  .z-card .z-badge,
  .z-card .z-known {
    font-size: 5px;
    padding: 0 2px;
  }

  .field-foot {
    margin: 7px 2px 8px;
    align-items: flex-end;
  }

  .status-strip {
    gap: 8px;
  }

  .stat-key {
    font-size: 6.5px;
  }

  .stat-val {
    font-size: 10px;
  }

  .mini-btn {
    padding: 3px 6px;
    font-size: 8px;
  }

  .hand-area {
    padding: 8px 9px 9px;
    border-radius: 12px;
  }

  .hand-card {
    width: 86px;
    height: 118px;
    padding: 6px;
  }

  .hand-card.is-selected {
    transform: translateY(-4px);
  }

  .hc-icon {
    font-size: 19px;
  }

  .hc-name {
    font-size: 8px;
  }

  .hc-stats {
    font-size: 7px;
  }

  .detail {
    font-size: 9.5px;
    min-height: 34px;
    padding: 6px 8px;
  }

  .action-bar {
    position: sticky;
    bottom: calc(6px + env(safe-area-inset-bottom));
    z-index: 40;
    min-height: 50px;
    padding: 7px 9px;
    margin-top: 7px;
    backdrop-filter: blur(12px);
  }

  .action-hint {
    font-size: 9.5px;
    flex-basis: 100%;
  }

  .action-btn {
    padding: 7px 12px;
    font-size: 11px;
  }

  .sidebar {
    grid-template-columns: minmax(0, 1fr);
  }

  .sidebar .puzzle-panel,
  .sidebar .log-panel {
    grid-column: auto;
  }

  .modal {
    padding: 18px 16px;
    max-height: 90dvh;
  }

  .result-stats {
    gap: 6px;
  }

  .result-stat .rs-val {
    font-size: 16px;
  }

  .modal-actions .btn {
    flex: 1 1 auto;
  }

  .toast {
    bottom: calc(68px + env(safe-area-inset-bottom));
  }
}

@media (max-width: 380px) {
  .zone-count {
    display: none;
  }

  .stat:nth-child(3) {
    display: none;
  }

  .hand-card {
    width: 80px;
    height: 112px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

content.text:
